    // summarizer, plus the debug log for post-mortems.
    if (failures.isNotEmpty) {
      final error = failures.last;
      AppLog.i('compaction', 'auto-compaction failed: $error');
      messages.add(
        FahChatMessage(
          role: 'system',
          content: appCompactionFailureNotice(error),
        ),
      );
