    gate.complete();
    await staleLoad;
    await Future<void>.delayed(Duration.zero);
    expect(service.currentSessionId, b.id);
    expect(
      service.messages.where((m) => m.content.contains('alpha-old')),
      isEmpty,
    );
  });

