  /// secret values — ids, paths, provider kinds, model ids.
  Map<String, String> _sessionEnvVars() => {
    sessionIdEnvVar: ?_sessionId,
    sessionFileEnvVar: ?_sessionFile,
    providerEnvVar: _providerKind,
    modelEnvVar: _agent.state.model.id,
