  bool shallowGiantCustoms = false,
}) async {
  if (lines.isEmpty) return const <SessionRecord?>[];
  final batches = splitSessionParseBatches(
    lines,
    filePath: filePath,
    firstLineNumber: firstLineNumber,
    shallowGiantCustoms: shallowGiantCustoms,
  );

