        session: _session!,
        state: _agent.state,
        window: conversationWindow,
        settings: settings,
        sources: AutoCompactorSources(
          smolStream: smolSlot?.stream,
          smolModel: smolSlot?.model,
          mainStream: _agent.streamFunction,
