  _ingestBelowWindow() async {
    final chunk = await _reader.readForward(_knownFileBytes);
    for (final entry in chunk.entries) {
      _offsetById[entry.record.id] = entry.offset;
      _appendedBelow[entry.record.id] = entry.record;
